<?php
declare(strict_types=1);
namespace CommunityHub;
final class View {
 public static function layout(string $title,callable $body):void {
  $u=Auth::user();$brand=Domain::branding();$path=parse_url($_SERVER['REQUEST_URI']??'/',PHP_URL_PATH);$role=$u['role']??'';
  $groups=['Operations'=>['/fivem'=>'Live operations','/fivem/status'=>'Server status','/reports'=>'Reports'],'Community'=>['/personnel'=>'People','/applications'=>'Recruitment','/news'=>'News','/rules'=>'Rules','/support'=>'Support','/home'=>'Community home','/about'=>'About','/gallery'=>'Gallery'],'Members'=>['/lms'=>'My training','/training'=>'Training sessions','/calendar'=>'Calendar','/documents'=>'Documents']];
  $admin=[];if(in_array($role,['reviewer',...Domain::STAFF],true))$admin['/admin']='Admin Center';if(in_array($role,Domain::STAFF,true)){$admin['/admin/management']='Community management';$admin['/admin/management/notifications']='Notifications';$admin['/staff-activity']='Staff activity';$admin['/loa-management']='Leave management';$admin['/command-center']='Command center';$admin['/command-center/readiness']='Department readiness';$admin['/lms/admin']='Course builder';}if(in_array($role,Domain::CONTENT_STAFF,true))$admin['/community/manage']='News & rules';if(in_array($role,Domain::ADMINS,true)){$admin['/admin/fivem']='FiveM configuration';$admin['/admin/application-builder']='Application builder';$admin['/lms/admin']='Course builder';$admin['/admin/appearance']='Appearance & in-game';$admin['/admin/website']='Website content';$admin['/admin/automations']='Automation flows';}if(in_array($role,['admin','owner'],true))$admin['/admin/users']='Accounts & roles';if($admin)$groups['Administration']=$admin;
  ?><!doctype html><html lang="en" data-theme="dark"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="light dark"><title><?=escape($title.' · '.$brand['name'])?></title><link rel="icon" href="/branding/icon"><script>document.documentElement.classList.add('js');try{const m=document.cookie.match(/(?:^|; )communityhub_theme=(light|dark|system)(?:;|$)/);const t=m?m[1]:'dark';document.documentElement.dataset.theme=t==='system'?(matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light'):t;}catch{}</script><?php foreach(['site','community','command','v3-people','community-content','v3-command-center','theme','php'] as $css):?><link rel="stylesheet" href="/css/<?=escape($css)?>.css"><?php endforeach?><script src="/js/navigation.js" defer></script><script src="/js/duty-timer.js" defer></script></head><body class="<?= $u?'hub-app':'public-site' ?> top-navigation"><a class="skip-link" href="#main-content">Skip to content</a><header class="community-topnav"><div class="topnav-inner"><a class="hub-brand" href="<?=$u?'/overview':'/'?>"><span class="brand-seal <?=$brand['logo']?'brand-logo':''?>" aria-hidden="true"><?php if($brand['logo']):?><img src="<?=escape($brand['logo'])?>" alt=""><?php else:?>CH<?php endif?></span><span><?=escape($brand['name'])?><small>Community Hub</small></span></a><button class="icon-button topnav-toggle" aria-controls="site-navigation" aria-expanded="false" aria-label="Open navigation">☰</button><nav id="site-navigation" class="topnav-links" aria-label="Main navigation"><a class="topnav-home" href="<?=$u?'/overview':'/'?>" <?=$path==='/'||$path==='/overview'?'aria-current="page"':''?>><?=$u?'Overview':'Home'?></a><?php foreach($groups as $name=>$items):?><details class="topnav-group"><summary class="<?=array_key_exists($path,$items)?'current-group':''?>"><?=escape($name)?></summary><div class="topnav-dropdown"><?php foreach($items as $url=>$label):?><a href="<?=escape($url)?>" <?=$path===$url?'aria-current="page"':''?>><span><?=escape($label)?></span></a><?php endforeach?></div></details><?php endforeach?></nav><div class="topnav-actions"><?php if($u):?><button class="icon-button" id="search-open" aria-label="Find a page"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><circle cx="10" cy="10" r="7"/><path d="m15 15 6 6"/></svg></button><a class="icon-button" href="/admin/management/notifications" aria-label="Notifications"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/></svg></a><?php endif?><button class="theme-toggle" data-theme-toggle aria-label="Color theme: Dark. Switch to Light"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><path data-theme-icon></path></svg><span data-theme-name>Dark</span></button><?php if($u):?><details class="account-dropdown"><summary><?php self::avatar($u);?><span class="account-brief"><?=escape($u['display_name']??$u['username'])?><small><?=escape(str_replace('_',' ',$role))?></small></span><span class="sr-only">Account menu</span></summary><div class="nav-menu-links"><a href="/account">Account settings & bio</a><form method="post" action="/auth/logout" class="nav-form"><?php self::csrf();?><button class="nav-link-button">Log out</button></form></div></details><?php else:?><a class="btn secondary topnav-login" href="/auth/login">Sign in with Discord</a><?php endif?></div></div></header><?php if($u):?><dialog class="page-search" id="page-search" aria-labelledby="page-search-title"><div class="search-title"><h2 id="page-search-title">Find a page</h2><button class="icon-button" id="search-close" aria-label="Close page search">×</button></div><label for="page-search-input" class="sr-only">Search pages</label><input id="page-search-input" type="search" placeholder="Search community pages…" autocomplete="off"><div class="search-results"><?php foreach([['/overview'=>'Overview','/account'=>'Account settings'],...array_values($groups)] as $items)foreach($items as $url=>$label):?><a href="<?=escape($url)?>" data-search-link><?=escape($label)?></a><?php endforeach?><p id="search-empty" hidden>No matching pages.</p></div></dialog><?php endif?><main id="main-content" tabindex="-1"><?php $body();?></main><footer><?=escape($brand['name'])?> · Community operations</footer></body></html><?php
 }
 public static function avatar(array $u):void{?><span class="account-picture" aria-hidden="true"><span><?=escape(mb_substr($u['display_name']??$u['username']??'M',0,1))?></span><?php if(!empty($u['avatar_url'])&&preg_match('~^https://cdn\.discordapp\.com/(avatars|embed/avatars)/~',$u['avatar_url'])):?><img src="<?=escape($u['avatar_url'])?>" alt="" referrerpolicy="no-referrer" data-avatar-image><?php endif?></span><?php }
 public static function csrf():void{?><input type="hidden" name="_csrf" value="<?=escape(Auth::token())?>"><?php }
 public static function heading(string $title,string $description='',string $eyebrow='COMMUNITY'):void{?><section class="page-head"><div><div class="eyebrow"><?=escape($eyebrow)?></div><h1><?=escape($title)?></h1><?php if($description):?><p><?=escape($description)?></p><?php endif?></div></section><?php }
 public static function message(string $title,string $message):void{self::layout($title,function()use($title,$message){self::heading($title);?><section class="panel"><p><?=escape($message)?></p></section><?php });}
 public static function table(array $rows,array $columns,?callable $actions=null):void{?><div class="table-scroll"><table class="community-table"><thead><tr><?php foreach($columns as $label):?><th><?=escape($label)?></th><?php endforeach?><?php if($actions):?><th>Actions</th><?php endif?></tr></thead><tbody><?php foreach($rows as $row):?><tr><?php foreach($columns as $key=>$label):?><td><?=escape($row[$key]??'—')?></td><?php endforeach?><?php if($actions):?><td><?php $actions($row);?></td><?php endif?></tr><?php endforeach?></tbody></table><?php if(!$rows):?><p class="muted">No records to display.</p><?php endif?></div><?php }
 public static function form(string $action,array $fields,string $submit='Save',array $values=[]):void{?><form method="post" action="<?=escape($action)?>" class="community-editor"><?php self::csrf();foreach($fields as $name=>$spec){$spec=is_string($spec)?['label'=>$spec]:$spec;$label=$spec['label']??$name;$type=$spec['type']??'text';$value=$values[$name]??$spec['default']??'';if($type==='hidden'){echo '<input type="hidden" name="'.escape($name).'" value="'.escape($value).'">';continue;}?><label><span><?=escape($label)?></span><?php if(isset($spec['options'])&&in_array($type,['checkbox','radio'],true)):foreach($spec['options'] as $k=>$v):?><span class="option-row"><input type="<?=escape($type)?>" name="<?=escape($name).($type==='checkbox'?'[]':'')?>" value="<?=escape($k)?>" <?=$type==='radio'&&!empty($spec['required'])?'required':''?>><?=escape($v)?></span><?php endforeach;elseif(isset($spec['options'])):?><select name="<?=escape($name)?>"><?php foreach($spec['options'] as $k=>$v):?><option value="<?=escape($k)?>" <?=(string)$value===(string)$k?'selected':''?>><?=escape($v)?></option><?php endforeach?></select><?php elseif($type==='textarea'):?><textarea name="<?=escape($name)?>" rows="5" <?=isset($spec['max'])?'maxlength="'.(int)$spec['max'].'"':''?> <?=!empty($spec['required'])?'required':''?>><?=escape($value)?></textarea><?php elseif($type==='checkbox'):?><input type="checkbox" name="<?=escape($name)?>" value="1" <?=$value?'checked':''?>><?php else:?><input type="<?=escape($type)?>" name="<?=escape($name)?>" value="<?=escape($value)?>" <?=isset($spec['max'])?'maxlength="'.(int)$spec['max'].'"':''?> <?=!empty($spec['required'])?'required':''?>><?php endif?></label><?php }?><button class="btn"><?=escape($submit)?></button></form><?php }
 public static function markdown(?string $text):void{static $converter=null;if(!$converter){$environment=new \League\CommonMark\Environment\Environment(['html_input'=>'escape','allow_unsafe_links'=>false,'renderer'=>['soft_break'=>"<br />\n"]]);$environment->addExtension(new \League\CommonMark\Extension\CommonMark\CommonMarkCoreExtension());$environment->addRenderer(\League\CommonMark\Extension\CommonMark\Node\Inline\Image::class,new class implements \League\CommonMark\Renderer\NodeRendererInterface {public function render(\League\CommonMark\Node\Node $node,\League\CommonMark\Renderer\ChildNodeRendererInterface $renderer):string{return '';}},100);$converter=new \League\CommonMark\MarkdownConverter($environment);}echo '<div class="community-reading">'.$converter->convert($text??'').'</div>';}
 public static function prose(?string $text):void{?><div class="community-text"><?=escape($text??'')?></div><?php }
}
